47: /*
48:  * NFC Quick Check from
49:  * http://unicode.org/reports/tr15/#Detecting_Normalization_Forms
50:  *
51:  * They say, this is much faster than 'brute force' normalization.
52:  * Strings are very likely already in NFC form.
53:  */
54: G_GNUC_IDN2_ATTRIBUTE_PURE static int
55: _isNFC (uint32_t *label, size_t len)
56: {
57:   int lastCanonicalClass = 0;
58:   int result = 1;
59:   size_t it;
60: 
61:   for (it = 0; it < len; it++)
62:     {
63:       uint32_t ch = label[it];
64: 
65:       // supplementary code point
66:       if (ch >= 0x10000)
67: 	it++;
68: 
69:       int canonicalClass = uc_combining_class (ch);
70:       if (lastCanonicalClass > canonicalClass && canonicalClass != 0)
71: 	return 0;
72: 
73:       NFCQCMap *map = get_nfcqc_map (ch);
74:       if (map)
75: 	{
76: 	  if (map->check)
77: 	    return 0;
78: 	  result = -1;
79: 	}
80: 
81:       lastCanonicalClass = canonicalClass;
82:     }
83: 
84:   return result;
85: }
86: 
87: int
88: _idn2_u8_to_u32_nfc (const uint8_t *src, size_t srclen,
89: 		     uint32_t **out, size_t *outlen, int nfc)
90: {
91:   uint32_t *p;
92:   size_t plen;
93: 
94:   p = u8_to_u32 (src, srclen, NULL, &plen);
95:   if (p == NULL)
96:     {
97:       if (errno == ENOMEM)
98: 	return IDN2_MALLOC;
99:       return IDN2_ENCODING_ERROR;
100:     }
101: 
102:   if (nfc && !_isNFC (p, plen))
103:     {
104:       size_t tmplen;
105:       uint32_t *tmp = u32_normalize (UNINORM_NFC, p, plen, NULL, &tmplen);
106:       free (p);
107:       if (tmp == NULL)
108: 	{
109: 	  if (errno == ENOMEM)
110: 	    return IDN2_MALLOC;
111: 	  return IDN2_NFC;
112: 	}
113: 
114:       p = tmp;
115:       plen = tmplen;
116:     }
117: 
118:   *out = p;
119:   *outlen = plen;
120:   return IDN2_OK;
121: }
122: 
123: bool
124: _idn2_ascii_p (const uint8_t *src, size_t srclen)
125: {
126:   size_t i;
127: 
128:   for (i = 0; i < srclen; i++)
129:     if (src[i] >= 0x80)
130:       return false;
131: 
132:   return true;
133: }
